"use client"

import type React from "react"

import { useState } from "react"
import Link from "next/link"
import { Sidebar } from "@/components/sidebar"
import { TopBar } from "@/components/topbar"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Card } from "@/components/ui/card"

interface Video {
  id: string
  title: string
  url: string
  date: string
  status: "processing" | "completed"
}

export default function DashboardPage() {
  const [videoUrl, setVideoUrl] = useState("")
  const [loading, setLoading] = useState(false)
  const [videos, setVideos] = useState<Video[]>([
    {
      id: "1",
      title: "Introduction to Machine Learning",
      url: "https://youtube.com/watch?v=example1",
      date: "2024-12-01",
      status: "completed",
    },
    {
      id: "2",
      title: "Advanced Python Concepts",
      url: "https://youtube.com/watch?v=example2",
      date: "2024-11-28",
      status: "processing",
    },
  ])

  const handleAddVideo = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!videoUrl.trim()) return

    setLoading(true)
    // Simulate API call
    setTimeout(() => {
      const newVideo: Video = {
        id: String(videos.length + 1),
        title: "New Lecture",
        url: videoUrl,
        date: new Date().toISOString().split("T")[0],
        status: "processing",
      }
      setVideos([newVideo, ...videos])
      setVideoUrl("")
      setLoading(false)
    }, 1000)
  }

  return (
    <div className="flex h-screen bg-background">
      <Sidebar />

      <div className="flex-1 flex flex-col overflow-hidden">
        <TopBar />

        <main className="flex-1 overflow-auto">
          <div className="p-8 max-w-6xl mx-auto space-y-8">
            {/* Add Video Section */}
            <Card className="p-6 border-border/50">
              <h2 className="text-xl font-semibold text-foreground mb-4">Add New Lecture</h2>
              <form onSubmit={handleAddVideo} className="space-y-4">
                <div className="space-y-2">
                  <label className="text-sm font-medium text-foreground">YouTube Video URL</label>
                  <div className="flex gap-3">
                    <Input
                      type="url"
                      placeholder="https://youtube.com/watch?v=..."
                      value={videoUrl}
                      onChange={(e) => setVideoUrl(e.target.value)}
                      className="flex-1"
                    />
                    <Button
                      type="submit"
                      disabled={loading || !videoUrl.trim()}
                      className="bg-primary hover:bg-primary/90"
                    >
                      {loading ? "Processing..." : "Add Lecture"}
                    </Button>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Paste a YouTube lecture URL to generate summary and concept map
                  </p>
                </div>
              </form>
            </Card>

            {/* Recent Videos */}
            <div className="space-y-4">
              <h2 className="text-xl font-semibold text-foreground">Recent Lectures</h2>
              <div className="grid gap-4">
                {videos.map((video) => (
                  <Card key={video.id} className="p-4 border-border/50 hover:border-border transition-colors">
                    <div className="flex items-center justify-between">
                      <div className="flex-1">
                        <h3 className="font-semibold text-foreground mb-1">{video.title}</h3>
                        <p className="text-sm text-muted-foreground">{video.date}</p>
                      </div>
                      <div className="flex items-center gap-3">
                        <div
                          className={`px-3 py-1 rounded-full text-xs font-medium ${
                            video.status === "completed"
                              ? "bg-green-500/10 text-green-700"
                              : "bg-yellow-500/10 text-yellow-700"
                          }`}
                        >
                          {video.status === "completed" ? "✓ Done" : "⏳ Processing"}
                        </div>
                        {video.status === "completed" && (
                          <div className="flex gap-2">
                            <Link href={`/summary/${video.id}`}>
                              <Button size="sm" variant="outline">
                                View Summary
                              </Button>
                            </Link>
                            <Link href={`/concept-map/${video.id}`}>
                              <Button size="sm" className="bg-accent hover:bg-accent/90">
                                View Map
                              </Button>
                            </Link>
                          </div>
                        )}
                      </div>
                    </div>
                  </Card>
                ))}
              </div>
            </div>
          </div>
        </main>
      </div>
    </div>
  )
}
